import os
import json
import hashlib
import hmac
import time
import tempfile
import stat

SECRET_KEY = os.environ.get('SESSION_SECRET', os.urandom(32).hex())
SESSION_DIR = os.environ.get('SESSION_DIR', '/tmp/sessions')

def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)

def compute_mac(data: bytes) -> str:
    return hmac.new(SECRET_KEY.encode(), data, hashlib.sha256).hexdigest()

def ensure_session_dir():
    os.makedirs(SESSION_DIR, mode=0o700, exist_ok=True)

def create_session(user_id: str, permissions: list) -> str:
    """Create a new session with cryptographic MAC for integrity."""
    ensure_session_dir()
    session_id = os.urandom(32).hex()
    session_data = {
        'user_id': user_id,
        'permissions': permissions,
        'created_at': time.time(),
        'expires_at': time.time() + 3600
    }
    payload = json.dumps(session_data, sort_keys=True).encode()
    mac = compute_mac(payload)
    session_file = os.path.join(SESSION_DIR, session_id)

    # Write session atomically
    fd = os.open(session_file, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        content = json.dumps({'data': session_data, 'mac': mac})
        os.write(fd, content.encode())
    finally:
        os.close(fd)

    return session_id

def validate_session(session_id: str) -> dict:
    """Validate session integrity and return session data."""
    # Sanitize session_id to prevent path traversal
    if not all(c in '0123456789abcdef' for c in session_id):
        raise ValueError("Invalid session ID format")
    if len(session_id) != 64:
        raise ValueError("Invalid session ID length")

    session_file = os.path.join(SESSION_DIR, session_id)

    # Open the file with O_NOFOLLOW to prevent symlink attacks,
    # then check permissions on the opened file descriptor
    try:
        fd = os.open(session_file, os.O_RDONLY | os.O_NOFOLLOW)
    except FileNotFoundError:
        raise ValueError("Session not found")
    except OSError:
        # O_NOFOLLOW raises OSError if path is a symlink
        raise ValueError("Session file is not a regular file")

    try:
        # fstat on the open fd - no TOCTOU possible
        file_stat = os.fstat(fd)

        # Verify file permissions are restrictive
        if file_stat.st_mode & 0o077 != 0:
            raise ValueError("Session file has insecure permissions")

        # Verify file is owned by us
        if file_stat.st_uid != os.getuid():
            raise ValueError("Session file ownership mismatch")

        # Verify it's a regular file
        if not stat.S_ISREG(file_stat.st_mode):
            raise ValueError("Session file is not a regular file")

        # Read from the same fd - atomic with respect to the checks above
        raw = os.read(fd, 65536)
        if len(raw) >= 65536:
            raise ValueError("Session file too large")
    finally:
        os.close(fd)

    content = json.loads(raw.decode('utf-8'))

    session_data = content['data']
    stored_mac = content['mac']

    # Verify MAC
    payload = json.dumps(session_data, sort_keys=True).encode()
    expected_mac = compute_mac(payload)

    if not constant_time_compare(stored_mac.encode(), expected_mac.encode()):
        raise ValueError("Session integrity check failed")

    # Check expiration
    if time.time() > session_data['expires_at']:
        revoke_session(session_id)
        raise ValueError("Session expired")

    return session_data

def revoke_session(session_id: str):
    """Securely revoke a session."""
    if not all(c in '0123456789abcdef' for c in session_id):
        raise ValueError("Invalid session ID format")
    if len(session_id) != 64:
        raise ValueError("Invalid session ID length")

    session_file = os.path.join(SESSION_DIR, session_id)
    try:
        os.unlink(session_file)
    except FileNotFoundError:
        pass

def refresh_session(session_id: str) -> str:
    """Refresh a session, returning a new session ID."""
    session_data = validate_session(session_id)
    revoke_session(session_id)
    return create_session(session_data['user_id'], session_data['permissions'])

def list_active_sessions(user_id: str) -> list:
    """List all active sessions for a user."""
    ensure_session_dir()
    active = []
    for filename in os.listdir(SESSION_DIR):
        if not all(c in '0123456789abcdef' for c in filename):
            continue
        if len(filename) != 64:
            continue
        try:
            session_data = validate_session(filename)
            if session_data['user_id'] == user_id:
                active.append({
                    'session_id': filename,
                    'created_at': session_data['created_at'],
                    'expires_at': session_data['expires_at']
                })
        except ValueError:
            continue
    return active
